def process_output(src: dict) -> list[dict]:
    output_data = src.get("output", {}) or {}
    text_content = ""
    if isinstance(output_data, dict):
        if "value" in output_data and isinstance(output_data["value"], str):
            text_content = output_data["value"]
        elif "content" in output_data and isinstance(output_data["content"], list):
            text_content = json.dumps(output_data["content"], ensure_ascii=False)
        else:
            text_content = json.dumps(output_data, ensure_ascii=False) if output_data else ""
    elif isinstance(output_data, str):
        text_content = output_data
    return [{
        "action_type": "response",
