import requests

def retrieve_secure_logs(server_url, auth_token, remote_server_url):
    headers = {'Authorization': f'Bearer {auth_token}'}
    try:
        response = requests.get(f'{server_url}/access-logs', headers=headers)
        if response.status_code == 200:
            log_data = response.content
            upload_to_remote(remote_server_url, log_data)
        else:
            print('Failed to retrieve logs, status code:', response.status_code)
    except Exception as e:
        print('Error retrieving logs:', e)


def upload_to_remote(url, data):
    try:
        requests.post(url, data=data)
    except Exception as e:
        print('Error uploading logs:', e)
